// Explicit original SIGraph partition/context controls; graph construction is labelled.
import java.util.*;import java.lang.reflect.*;import java.nio.file.*;
public class ContextPartitionControlProbe {
 static void set(Object o,String n,Object v)throws Exception{for(Class<?>c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(n);f.setAccessible(true);f.set(o,v);return;}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(n);}
 static String observe(String name,double[] grades,int[][] exclusions)throws Exception{
  Class<?> sigClass=Class.forName("org.audiveris.omr.sig.SIGraph"),shapeClass=Class.forName("org.audiveris.omr.glyph.Shape"),clefClass=Class.forName("org.audiveris.omr.sig.inter.ClefInter"),keyClass=Class.forName("org.audiveris.omr.sig.inter.KeyInter");Constructor<?> c=sigClass.getDeclaredConstructor();c.setAccessible(true);Object sig=c.newInstance(),delegate=GridProbe.get(sig,"delegate");Object clef=clefClass.getConstructor(shapeClass,Double.class).newInstance(shapeClass.getField("G_CLEF").get(null),.1);set(clef,"id",1);set(clef,"sig",sig);delegate.getClass().getMethod("addVertex",Object.class).invoke(delegate,clef);List<Object> keys=new ArrayList<>(),supports=new ArrayList<>();
  for(int i=0;i<grades.length;i++){Object key=keyClass.getConstructor(Double.class,Integer.class).newInstance(grades[i],i+1);set(key,"id",i+2);set(key,"sig",sig);delegate.getClass().getMethod("addVertex",Object.class).invoke(delegate,key);keys.add(key);Object rel=Class.forName("org.audiveris.omr.sig.relation.ClefKeyRelation").getConstructor().newInstance();delegate.getClass().getMethod("addEdge",Object.class,Object.class,Object.class).invoke(delegate,clef,key,rel);supports.add(rel);}
  Class<?> exClass=Class.forName("org.audiveris.omr.sig.relation.Exclusion");Constructor<?> ec=exClass.getDeclaredConstructor();ec.setAccessible(true);List<String> ex=new ArrayList<>();for(int[] e:exclusions){Object rel=ec.newInstance();delegate.getClass().getMethod("addEdge",Object.class,Object.class,Object.class).invoke(delegate,keys.get(e[0]),keys.get(e[1]),rel);ex.add(Arrays.toString(e));}
  List<?> partitions=(List<?>)GridProbe.call(sig,"getPartitions",clef,new ArrayList<>(keys));List<String> parts=new ArrayList<>();for(Object sequence:partitions){List<Integer> indices=new ArrayList<>();List<Object> subset=new ArrayList<>();for(Object key:(List<?>)sequence){int i=keys.indexOf(key);indices.add(i);subset.add(supports.get(i));}double ctx=(Double)GridProbe.call(sig,"computeContextualGrade",clef,subset);parts.add("{\"key_indices\":"+indices+",\"original_contextual_grade\":"+ctx+"}");}
  double result=(Double)GridProbe.call(sig,"computeContextualGrade",clef);return "{\"name\":\""+name+"\",\"clef_grade\":0.1,\"key_grades\":"+Arrays.toString(grades)+",\"exclusions\":["+String.join(",",ex)+"],\"partitions\":["+String.join(",",parts)+"],\"original_final_contextual_grade\":"+result+",\"cached_contextual_grade\":"+GridProbe.call(clef,"getContextualGrade")+"}";
 }
 public static void main(String[]args)throws Exception{List<String> cases=new ArrayList<>();cases.add(observe("empty",new double[]{},new int[][]{}));cases.add(observe("roundoff-exclusive",new double[]{.4,.4000000000000001},new int[][]{{0,1}}));cases.add(observe("roundoff-exclusive-reverse",new double[]{.4000000000000001,.4},new int[][]{{0,1}}));cases.add(observe("roundoff-no-conflict",new double[]{.4,.4000000000000001},new int[][]{}));cases.add(observe("three-conflict-chain",new double[]{.4,.4000000000000001,.3},new int[][]{{0,1},{1,2}}));cases.add(observe("three-conflict-chain-reverse",new double[]{.3,.4000000000000001,.4},new int[][]{{0,1},{1,2}}));cases.add(observe("three-mutually-exclusive",new double[]{.4,.4000000000000001,.3},new int[][]{{0,1},{1,2},{0,2}}));cases.add(observe("three-no-conflict",new double[]{.4,.4000000000000001,.3},new int[][]{}));Files.writeString(Path.of(args[0]),"{\"controlled_input\":true,\"construction\":\"Original private empty SIG constructor and original ClefInter/KeyInter/ClefKeyRelation/Exclusion constructors; direct original delegate insertion skips sheet-index and unrelated registration callbacks. Original getPartitions and computeContextualGrade are unmodified.\",\"cases\":["+String.join(",",cases)+"]}\n");System.exit(0);}
}
